import { useEffect, useState } from "react";
import ModalWindow from "../ModalWindow";
import "./TrainerShedule.css";
import { getTrainerSheduleByTrainerId } from "../../../Services/TrainerAvailabilityService";
import { TrainerAvailability } from "../../../Interfaces/TrainerAvailability/TrainerAvailability";
import { TrainerWithUser } from "../../../Interfaces/Trainer/TrainerWithUserInterface";

interface TrainerSheduleProps {
  isOpen: boolean;
  onClose: () => void;
  trainer?: TrainerWithUser;
}

const TrainerShedule = ({ isOpen, onClose, trainer }: TrainerSheduleProps) => {
  const [schedule, setSchedule] = useState<TrainerAvailability[] | null>(null);
  const [loading, setLoading] = useState(false);

  // Стан вибраного елемента розкладу
  const [selectedEntry, setSelectedEntry] =
    useState<TrainerAvailability | null>(null);

  useEffect(() => {
    if (!isOpen || !trainer?.trainer?.id) return;

    const fetchSchedule = async () => {
      setLoading(true);
      const scheduleRes = await getTrainerSheduleByTrainerId(
        trainer.trainer.id
      );
      setSchedule(scheduleRes);
      setLoading(false);
    };

    fetchSchedule();

    // Скидаємо вибране при відкритті модалки
    setSelectedEntry(null);
  }, [isOpen, trainer]);

  if (!trainer) return null;

  return (
    <ModalWindow isOpen={isOpen} onClose={onClose}>
      <div className="trainer-schedule">
        <h2>
          Schedule for {trainer.user.firstName} {trainer.user.lastName}
        </h2>

        {loading ? (
          <p>Loading schedule...</p>
        ) : schedule && schedule.length > 0 ? (
          <>
            <ul className="schedule-list">
              {schedule.map((entry) => (
                <li
                  key={entry.id}
                  onClick={() => setSelectedEntry(entry)}
                  className={selectedEntry?.id === entry.id ? "selected" : ""}
                  style={{
                    cursor: "pointer",
                    padding: "5px",
                    borderRadius: "4px",
                  }}
                >
                  <strong>Day:</strong> {getDayName(entry.dayOfWeek)} |{" "}
                  <strong>Time:</strong> {formatTime(entry.startTime)} -{" "}
                  {formatTime(entry.endTime)}
                </li>
              ))}
            </ul>

            {selectedEntry && (
              <div
                className="selected-entry-details"
                style={{ marginTop: "15px" }}
              >
                <h3>Selected Schedule Entry:</h3>
                <p>
                  <strong>Day:</strong> {getDayName(selectedEntry.dayOfWeek)}
                </p>
                <p>
                  <strong>Time:</strong> {formatTime(selectedEntry.startTime)} -{" "}
                  {formatTime(selectedEntry.endTime)}
                </p>
              </div>
            )}
          </>
        ) : (
          <p>No schedule available.</p>
        )}
      </div>
    </ModalWindow>
  );
};

export default TrainerShedule;

const getDayName = (day: number) => {
  const days = [
    "Sunday",
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday",
  ];
  return days[day] || "Unknown";
};

const formatTime = (timeString: string) => {
  // Беремо "HH:mm" з рядка типу "HH:mm:ss" чи "HH:mm"
  return timeString.slice(0, 5);
};
